import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand authored PTX kernel implementing a split-K tiled GEMM:
#   C(M,N) += A(M,K_local) @ B(K_local,N)      (accumulated via atomic add)
#
# Layout assumptions (all row-major, contiguous):
#   A : (M, K_full)   element (m,k)      -> A[m*K_full + k]
#   B : (K_full, N)   element (k,n)      -> B[k*N + n]
#   C : (M, N)        element (m,n)      -> C[m*N + n]
#
# Grid:  (M/32, N/32, K_split)
# Block: (32, 32, 1)   -> one thread per output element of a 32x32 CTA tile
#
# Each CTA loads 32x32 tiles of A and B into shared memory, iterates over
# K_local in steps of 32, and accumulates a partial dot-product.  The final
# partial result is atomically added into the (pre-zeroed) global C tensor,
# implementing the split-K reduction across blockIdx.z.
#
# Optimization applied in this version:
#   Vectorized (128-bit) global-memory loads / shared-memory stores for the
#   A and B tile staging.  Within each warp (fixed ty, tx = 0..31) the 32
#   elements needed from A (contiguous along k) and from B (contiguous
#   along n) are loaded using ld.global.v4.f32 / st.shared.v4.f32 by only
#   1-in-4 lanes (tx % 4 == 0), each fetching/storing 4 contiguous floats
#   at once.  This reduces the number of global memory transactions and
#   shared-memory store instructions issued per K-tile by 4x while
#   preserving the exact same shared-memory tile layout (and therefore the
#   same downstream compute loop), which matters a great deal here because
#   K is extremely large (many thousands of K-tile iterations per CTA).
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry gemm_splitk_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K_local,
    .param .u32 K_full
)
{
    .reg .pred %p<8>;
    .reg .b32  %r<80>;
    .reg .b64  %rd<80>;
    .reg .f32  %f<20>;
    .shared .align 16 .b8 sA[4096];
    .shared .align 16 .b8 sB[8192];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [M];
    ld.param.u32 %r2,  [N];
    ld.param.u32 %r3,  [K_local];
    ld.param.u32 %r4,  [K_full];
    cvta.to.global.u64 %rd4, %rd1;   // A (global)
    cvta.to.global.u64 %rd5, %rd2;   // B (global)
    cvta.to.global.u64 %rd6, %rd3;   // C (global)
    mov.u32 %r5, %ctaid.x;
    mov.u32 %r6, %ctaid.y;
    mov.u32 %r7, %ctaid.z;
    mov.u32 %r8, %tid.x;             // tx (0..31), also selects n0/n1 columns
    mov.u32 %r9, %tid.y;             // ty (0..31), m-row / B k-row index
    // predicate: only lanes with tx % 4 == 0 perform the vectorized
    // (float4) global load + shared store for this K-tile iteration.
    and.b32    %r36, %r8, 3;
    setp.eq.s32 %p3, %r36, 0;
    mad.lo.s32 %r10, %r5, 32, %r9;   // m  = blockIdx.x*32 + ty
    mul.lo.s32 %r40, %r6, 64;        // n_base = blockIdx.y*64
    add.s32    %r11, %r40, %r8;      // n0 = n_base + tx
    add.s32    %r41, %r11, 32;       // n1 = n0 + 32
    mul.lo.s32 %r12, %r7, %r3;       // k_start = blockIdx.z * K_local
    mov.f32 %f1, 0f00000000;         // accumulator for n0
    mov.f32 %f12, 0f00000000;        // accumulator for n1
    shr.u32 %r13, %r3, 5;            // num_k_tiles = K_local / 32
    mov.u32 %r14, 0;                 // kt = 0
    // shared-mem store address for A tile: sA[ty][tx]
    mad.lo.s32 %r15, %r9, 32, %r8;
    shl.b32    %r16, %r15, 2;
    mov.u32    %r17, sA;
    add.s32    %r18, %r17, %r16;     // &sA[ty][tx]
    // shared-mem store addresses for B tile: sB[ty][tx] and sB[ty][tx+32]
    mul.lo.s32 %r42, %r9, 64;
    add.s32    %r43, %r42, %r8;
    shl.b32    %r44, %r43, 2;
    mov.u32    %r19, sB;
    add.s32    %r20, %r19, %r44;     // &sB[ty][tx]      (half0 store)
    add.s32    %r45, %r43, 32;
    shl.b32    %r46, %r45, 2;
    add.s32    %r47, %r19, %r46;     // &sB[ty][tx+32]   (half1 store)
    // base addresses used in the inner compute loop
    mul.lo.s32 %r21, %r9, 32;
    shl.b32    %r22, %r21, 2;
    add.s32    %r23, %r17, %r22;     // &sA[ty][0]
    shl.b32    %r24, %r8, 2;
    add.s32    %r25, %r19, %r24;     // &sB[0][tx]        (half0 base)
    add.s32    %r49, %r8, 32;
    shl.b32    %r50, %r49, 2;
    add.s32    %r51, %r19, %r50;     // &sB[0][tx+32]     (half1 base)
    // widen values needed for 64-bit address arithmetic
    cvt.s64.s32 %rd7,  %r10;         // m
    cvt.s64.s32 %rd8,  %r4;          // K_full
    cvt.s64.s32 %rd9,  %r11;         // n0
    cvt.s64.s32 %rd40, %r41;         // n1
    cvt.s64.s32 %rd10, %r2;          // N
$LOOP_K:
    setp.ge.u32 %p1, %r14, %r13;
    @%p1 bra $LOOP_K_END;
    // k index used for the A load: k_start + kt*32 + tx
    mul.lo.s32 %r26, %r14, 32;
    add.s32    %r27, %r12, %r26;
    add.s32    %r28, %r27, %r8;
    cvt.s64.s32 %rd12, %r28;
    // A element index = m*K_full + k
    mul.lo.s64 %rd13, %rd7, %rd8;
    add.s64    %rd14, %rd13, %rd12;
    shl.b64    %rd15, %rd14, 2;
    add.s64    %rd16, %rd4, %rd15;
    @%p3 ld.global.v4.f32 {%f2,%f3,%f4,%f5}, [%rd16];
    @%p3 st.shared.v4.f32 [%r18], {%f2,%f3,%f4,%f5};
    // k index used for the B load (row): k_start + kt*32 + ty
    add.s32    %r29, %r27, %r9;
    cvt.s64.s32 %rd17, %r29;
    // B element index (half0, columns n0..n0+3) = k*N + n0
    mul.lo.s64 %rd18, %rd17, %rd10;
    add.s64    %rd19, %rd18, %rd9;
    shl.b64    %rd20, %rd19, 2;
    add.s64    %rd21, %rd5, %rd20;
    @%p3 ld.global.v4.f32 {%f6,%f7,%f8,%f9}, [%rd21];
    @%p3 st.shared.v4.f32 [%r20], {%f6,%f7,%f8,%f9};
    // B element index (half1, columns n1..n1+3) = k*N + n1
    add.s64    %rd41, %rd18, %rd40;
    shl.b64    %rd42, %rd41, 2;
    add.s64    %rd43, %rd5, %rd42;
    @%p3 ld.global.v4.f32 {%f13,%f14,%f15,%f16}, [%rd43];
    @%p3 st.shared.v4.f32 [%r47], {%f13,%f14,%f15,%f16};
    bar.sync 0;
    // inner product over the 32-wide K tile; each thread now reuses a
    // single A value from shared memory against two B values, computing
    // two output columns (register/thread tiling, TN = 2).
    mov.u32 %r30, 0;
$LOOP_INNER:
    setp.ge.u32 %p2, %r30, 32;
    @%p2 bra $LOOP_INNER_END;
    shl.b32 %r31, %r30, 2;
    add.s32 %r32, %r23, %r31;        // &sA[ty][kk]
    ld.shared.f32 %f10, [%r32];
    mul.lo.s32 %r33, %r30, 64;        // row stride = BLOCK_N = 64
    shl.b32    %r34, %r33, 2;
    add.s32    %r35, %r25, %r34;      // &sB[kk][tx]        (half0)
    ld.shared.f32 %f11, [%r35];
    add.s32    %r52, %r51, %r34;      // &sB[kk][tx+32]     (half1)
    ld.shared.f32 %f17, [%r52];
    fma.rn.f32 %f1,  %f10, %f11, %f1;
    fma.rn.f32 %f12, %f10, %f17, %f12;
    add.s32 %r30, %r30, 1;
    bra.uni $LOOP_INNER;
$LOOP_INNER_END:
    bar.sync 0;
    add.s32 %r14, %r14, 1;
    bra.uni $LOOP_K;
$LOOP_K_END:
    // atomically accumulate partial results into C[m*N+n0] and C[m*N+n1]
    mul.lo.s64 %rd22, %rd7, %rd10;
    add.s64    %rd23, %rd22, %rd9;
    shl.b64    %rd24, %rd23, 2;
    add.s64    %rd25, %rd6, %rd24;
    red.global.add.f32 [%rd25], %f1;
    add.s64    %rd44, %rd22, %rd40;
    shl.b64    %rd45, %rd44, 2;
    add.s64    %rd46, %rd6, %rd45;
    red.global.add.f32 [%rd46], %f12;
    ret;
}
